CREATE SCHEMA IF NOT EXISTS library_q3; SET search_path TO library_q3,public;
CREATE TABLE IF NOT EXISTS books(book_id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,title TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS loans(loan_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,book_id INT NOT NULL REFERENCES books,borrower_name TEXT NOT NULL,borrowed_on DATE NOT NULL,due_on DATE NOT NULL,returned_on DATE,fine_amount NUMERIC(12,2) NOT NULL DEFAULT 0 CHECK(fine_amount>=0),CHECK(due_on>=borrowed_on),CHECK(returned_on IS NULL OR returned_on>=borrowed_on));
CREATE TABLE IF NOT EXISTS loan_audit(audit_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,loan_id BIGINT NOT NULL REFERENCES loans,old_returned_on DATE,new_returned_on DATE,changed_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS overdue_summary(snapshot_date DATE PRIMARY KEY,overdue_count BIGINT NOT NULL,total_fine NUMERIC(14,2) NOT NULL);
INSERT INTO books(book_id,title) VALUES(1,'Database Systems'),(2,'Clean Code'),(3,'Computer Networks') ON CONFLICT DO NOTHING;
INSERT INTO loans(loan_id,book_id,borrower_name,borrowed_on,due_on,returned_on,fine_amount) VALUES(1,1,'Alice',CURRENT_DATE-20,CURRENT_DATE-10,NULL,0),(2,2,'Ben',CURRENT_DATE-8,CURRENT_DATE-2,CURRENT_DATE-2,0),(3,3,'Cara',CURRENT_DATE-12,CURRENT_DATE-5,CURRENT_DATE-3,6),(4,1,'David',CURRENT_DATE-5,CURRENT_DATE+2,NULL,0),(5,2,'Eve',CURRENT_DATE-15,CURRENT_DATE-7,NULL,0),(6,3,'Frank',CURRENT_DATE-4,CURRENT_DATE+3,NULL,0) ON CONFLICT DO NOTHING;
CREATE OR REPLACE FUNCTION fn_loan_fine(p_loan_id BIGINT,p_as_of DATE) RETURNS NUMERIC(12,2) LANGUAGE plpgsql AS $$
DECLARE v_due DATE; v_return DATE; v_end DATE;
BEGIN SELECT due_on,returned_on INTO v_due,v_return FROM loans WHERE loan_id=p_loan_id; IF NOT FOUND THEN RAISE EXCEPTION 'Unknown loan %',p_loan_id; END IF; IF p_as_of IS NULL THEN RAISE EXCEPTION 'As-of date required'; END IF; v_end:=LEAST(p_as_of,COALESCE(v_return,p_as_of)); RETURN GREATEST(v_end-v_due,0)*2.00; END $$;
CREATE OR REPLACE FUNCTION fn_audit_loan_return() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN IF NEW.returned_on IS DISTINCT FROM OLD.returned_on THEN INSERT INTO loan_audit(loan_id,old_returned_on,new_returned_on) VALUES(NEW.loan_id,OLD.returned_on,NEW.returned_on); END IF; RETURN NEW; END $$;
DROP TRIGGER IF EXISTS trg_loan_return_audit ON loans;
CREATE TRIGGER trg_loan_return_audit AFTER UPDATE ON loans FOR EACH ROW EXECUTE FUNCTION fn_audit_loan_return();
CREATE OR REPLACE PROCEDURE pr_return_loan(p_loan_id BIGINT,p_returned_on DATE) LANGUAGE plpgsql AS $$
DECLARE v_borrowed DATE; v_return DATE; v_fine NUMERIC(12,2);
BEGIN SELECT borrowed_on,returned_on INTO v_borrowed,v_return FROM loans WHERE loan_id=p_loan_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Unknown loan'; END IF; IF v_return IS NOT NULL THEN RAISE EXCEPTION 'Loan already returned'; END IF; IF p_returned_on IS NULL OR p_returned_on<v_borrowed THEN RAISE EXCEPTION 'Invalid return date'; END IF; v_fine:=GREATEST(p_returned_on-(SELECT due_on FROM loans WHERE loan_id=p_loan_id),0)*2.00; UPDATE loans SET returned_on=p_returned_on,fine_amount=v_fine WHERE loan_id=p_loan_id; END $$;
CREATE OR REPLACE VIEW v_overdue_loans AS SELECT b.title,l.borrower_name,l.due_on,fn_loan_fine(l.loan_id,CURRENT_DATE) AS fine_as_of_today FROM loans l JOIN books b USING(book_id) WHERE l.returned_on IS NULL AND l.due_on<CURRENT_DATE;
CREATE INDEX IF NOT EXISTS ix_loans_open_by_book ON loans(book_id) WHERE returned_on IS NULL;
EXPLAIN SELECT * FROM loans WHERE book_id=1 AND returned_on IS NULL;
CREATE OR REPLACE PROCEDURE pr_refresh_overdue(p_as_of DATE) LANGUAGE plpgsql AS $$
BEGIN IF p_as_of IS NULL THEN RAISE EXCEPTION 'Snapshot date required'; END IF; INSERT INTO overdue_summary SELECT p_as_of,count(*) FILTER(WHERE returned_on IS NULL AND due_on<p_as_of),COALESCE(sum(fn_loan_fine(loan_id,p_as_of)) FILTER(WHERE returned_on IS NULL AND due_on<p_as_of),0) FROM loans ON CONFLICT(snapshot_date) DO UPDATE SET overdue_count=EXCLUDED.overdue_count,total_fine=EXCLUDED.total_fine; END $$;
CALL pr_refresh_overdue(CURRENT_DATE);
-- Schedule daily at 00:10: CALL library_q3.pr_refresh_overdue(CURRENT_DATE).
SELECT * FROM v_overdue_loans; SELECT * FROM loan_audit;